role_assignments = {
    "/subscriptions/sub1": [("alice", "Reader")],
    "/subscriptions/sub1/resourceGroups/rg-prod": [("bob", "Contributor")],
    "/subscriptions/sub1/resourceGroups/rg-prod/providers/Microsoft.Sql/servers/sql1": [("carol", "SQL DB Contributor")],
}

def effective_roles(resource_scope, assignments):
    ancestors = [s for s in assignments if resource_scope == s or resource_scope.startswith(s + "/")]
    roles = {}
    for scope in ancestors:
        for user, role in assignments[scope]:
            roles.setdefault(user, set()).add(role)
    return roles

target = "/subscriptions/sub1/resourceGroups/rg-prod/providers/Microsoft.Sql/servers/sql1"
effective = effective_roles(target, role_assignments)

for user in sorted(effective):
    print(user, "->", sorted(effective[user]))
